import { FormEvent, Suspense, useEffect, useState } from 'react'
import { NavLink, Navigate, Route, Routes, useLocation, useNavigate } from 'react-router-dom'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import * as Dialog from '@radix-ui/react-dialog'
import {
  Activity, Archive, BadgeDollarSign, Boxes, Car, ChevronDown, ChevronLeft, CircleDollarSign,
  ClipboardCheck, Command, FileCheck2, FileText, Gauge, Menu, Moon, PackageSearch, PanelLeftClose,
  Plus, ReceiptText, Search, Settings, ShieldCheck, ShoppingCart, Sun, Truck, Users, Warehouse,
  Wrench, X, AlertTriangle, ArrowUpRight, Download, DatabaseBackup, LogOut
} from 'lucide-react'
